    private void bEqActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_bEqActionPerformed
       num2=Double.parseDouble(t1.getText());
       double ans=0;
       if(Operator=="+"){
          ans=num1+num2; 
       }
       if(Operator=="-"){
          ans=num1-num2; 
       }
       if(Operator=="/"){
          ans=num1/num2; 
       }
    if(Operator=="*"){
          ans=num1*num2; 
       }
    t1.setText(""+ans);
    Operator=null;
    }//GEN-LAST:event_bEqActionPerformed

